Item.method_code:
const state = options.getState();
const rowId = state.grid.selectedRows[0];
const itemNode = window.currQryItem.getResult().selectSingleNode('Item[@id="' + rowId + '"]');
if (itemNode) {
	const topWindow = aras.getMostTopWindowWithAras(window);
	topWindow.ArasCore.Dialogs.properties(itemNode, options.itemType, {aras: aras});
}
